            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
            if len(mst_edges) == n - 1:
                break
